public class Signal {

    public enum Light { RED, GREEN, YELLOW }

    public static Light next(Light l) {
        switch (l) {
            case GREEN:
                return Light.YELLOW;
            case YELLOW:
                return Light.RED;
            default:
                return Light.GREEN;
        }
    }

    public static boolean isGo(Light l) {
        return l == Light.GREEN;
    }
}
